class Solution:
    def daysBetweenDates(self, date1: str, date2: str) -> int:
        def parse(s):
            y, m, d = map(int, s.split('-'))
            return [y, m, d]
        def leap(y):
            return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
        def mdays(y, m):
            if m == 2:
                return 29 if leap(y) else 28
            return [31,28,31,30,31,30,31,31,30,31,30,31][m-1]
        a, b = parse(date1), parse(date2)
        if a > b:
            a, b = b, a
        cnt = 0
        while a != b:
            a[2] += 1
            if a[2] > mdays(a[0], a[1]):
                a[2] = 1
                a[1] += 1
                if a[1] > 12:
                    a[1] = 1
                    a[0] += 1
            cnt += 1
        return cnt

