        int y1 = Integer.parseInt(date1.substring(0,4)), m1 = Integer.parseInt(date1.substring(5,7)), d1 = Integer.parseInt(date1.substring(8,10));
        int y2 = Integer.parseInt(date2.substring(0,4)), m2 = Integer.parseInt(date2.substring(5,7)), d2 = Integer.parseInt(date2.substring(8,10));
        if (y1 * 10000 + m1 * 100 + d1 > y2 * 10000 + m2 * 100 + d2) {
            int t;
            t = y1; y1 = y2; y2 = t;
            t = m1; m1 = m2; m2 = t;
            t = d1; d1 = d2; d2 = t;
