var daysBetweenDates = function(date1, date2) {
    const f = s => {
        const [y, m, d] = s.split('-').map(Number);
        const leap = yy => yy % 4 === 0 && (yy % 100 !== 0 || yy % 400 === 0);
        const pre = [0,31,59,90,120,151,181,212,243,273,304,334];
        let total = 365 * (y - 1) + Math.floor((y - 1) / 4) - Math.floor((y - 1) / 100) + Math.floor((y - 1) / 400);
        total += pre[m - 1] + d;
        if (m > 2 && leap(y)) total += 1;
        return total;
    };
    return Math.abs(f(date1) - f(date2));
};
